SELECT "list_users_by_status"."id", "list_users_by_status"."email", "list_users_by_status"."name", "list_users_by_status"."nickname", "list_users_by_status"."age", "list_users_by_status"."status", "list_users_by_status"."prev_status", "list_users_by_status"."balance", "list_users_by_status"."score", "list_users_by_status"."is_admin", "list_users_by_status"."tags", "list_users_by_status"."meta", "list_users_by_status"."settings", "list_users_by_status"."external_id", "list_users_by_status"."manager_id", "list_users_by_status"."birthday", "list_users_by_status"."created_at" FROM (SELECT id, email, name, nickname, age, status, prev_status, balance, score, is_admin, tags, meta, settings, external_id, manager_id, birthday, created_at FROM users WHERE status = $1) AS "list_users_by_status" ORDER BY "list_users_by_status"."created_at" DESC, "list_users_by_status"."id" DESC
